"""Exception hierarchy for kvstore."""

from __future__ import annotations

import os
import pathlib


class KVStoreError(Exception):
    """Base class for every kvstore error."""


class RecordError(KVStoreError):
    """A single record could not be decoded."""


class IncompleteRecordError(RecordError):
    """Fewer bytes are available than the record needs."""


class CorruptRecordError(RecordError):
    """The record bytes are present but invalid."""


class CorruptSegmentError(KVStoreError):
    """A segment file contains a corrupt record."""

    def __init__(self, path: str | os.PathLike, offset: int, reason: str) -> None:
        self.path = pathlib.Path(path)
        self.offset = offset
        self.reason = reason
        super().__init__(
            f"corrupt record in {self.path.name} at offset {offset}: {reason}"
        )

"""Binary record codec.

Layout (big-endian): magic(4) flags(1) key_len(2) value_len(4) crc(4) key value.
"""

from __future__ import annotations

import struct
import zlib

from .errors import CorruptRecordError, IncompleteRecordError

MAGIC = b"KVR1"
HEADER = struct.Struct(">4sBHII")
HEADER_SIZE = HEADER.size
FLAG_VALUE = 0x00
FLAG_TOMBSTONE = 0x01
MAX_KEY_BYTES = 0xFFFF
MAX_VALUE_BYTES = 0xFFFFFFFF


def encode_key(key: str) -> bytes:
    """Validate ``key`` and return its UTF-8 bytes."""
    if not isinstance(key, str):
        raise TypeError(f"key must be str, not {type(key).__name__}")
    key_bytes = key.encode("utf-8")
    if not 1 <= len(key_bytes) <= MAX_KEY_BYTES:
        raise ValueError(
            f"key must encode to 1..{MAX_KEY_BYTES} UTF-8 bytes, got {len(key_bytes)}"
        )
    return key_bytes


def encode_value(value: str) -> bytes:
    """Validate ``value`` and return its UTF-8 bytes."""
    if not isinstance(value, str):
        raise TypeError(f"value must be str, not {type(value).__name__}")
    value_bytes = value.encode("utf-8")
    if len(value_bytes) > MAX_VALUE_BYTES:
        raise ValueError("value is too large")
    return value_bytes


def encode_record(key: str, value: str | None) -> bytes:
    """Encode a record; ``value=None`` encodes a tombstone."""
    key_bytes = encode_key(key)
    if value is None:
        flags, value_bytes = FLAG_TOMBSTONE, b""
    else:
        flags, value_bytes = FLAG_VALUE, encode_value(value)
    body = key_bytes + value_bytes
    header = HEADER.pack(MAGIC, flags, len(key_bytes), len(value_bytes), zlib.crc32(body))
    return header + body


def record_size(buf: bytes, offset: int = 0) -> int:
    """Return the total size of the record at ``offset`` after structural checks."""
    if offset < 0:
        raise ValueError("offset must be non-negative")
    if len(buf) - offset < HEADER_SIZE:
        raise IncompleteRecordError("incomplete header")
    magic, flags, key_len, value_len, _ = HEADER.unpack_from(buf, offset)
    if magic != MAGIC:
        raise CorruptRecordError(f"bad magic {bytes(magic)!r}")
    if flags not in (FLAG_VALUE, FLAG_TOMBSTONE):
        raise CorruptRecordError(f"unknown flags 0x{flags:02x}")
    if key_len == 0:
        raise CorruptRecordError("key_len is 0")
    if flags == FLAG_TOMBSTONE and value_len != 0:
        raise CorruptRecordError("tombstone with non-zero value_len")
    return HEADER_SIZE + key_len + value_len


def decode_record(buf: bytes, offset: int = 0) -> tuple[str, str | None, int]:
    """Decode the record at ``buf[offset]`` into ``(key, value, total_size)``."""
    total = record_size(buf, offset)
    if len(buf) - offset < total:
        raise IncompleteRecordError("incomplete body")
    _, flags, key_len, _, crc = HEADER.unpack_from(buf, offset)
    body = bytes(buf[offset + HEADER_SIZE : offset + total])
    if zlib.crc32(body) != crc:
        raise CorruptRecordError("CRC mismatch")
    try:
        key = body[:key_len].decode("utf-8")
        value = body[key_len:].decode("utf-8")
    except UnicodeDecodeError as exc:
        raise CorruptRecordError(f"invalid UTF-8: {exc}") from None
    return key, (None if flags == FLAG_TOMBSTONE else value), total

"""A single append-only segment file."""

from __future__ import annotations

import os
import pathlib
import re
from typing import BinaryIO, Iterator

from .errors import CorruptRecordError, CorruptSegmentError, IncompleteRecordError
from .record import HEADER_SIZE, decode_record, record_size

SEGMENT_RE = re.compile(r"[0-9]{6}\.seg")


def segment_path(root: pathlib.Path, seg_id: int) -> pathlib.Path:
    """Return the path of segment ``seg_id`` inside ``root``."""
    return root / f"{seg_id:06d}.seg"


def segment_ids(root: pathlib.Path) -> list[int]:
    """Return the ids of every ``<id>.seg`` file in ``root``, ascending."""
    ids = [
        int(entry.name[:6])
        for entry in root.iterdir()
        if SEGMENT_RE.fullmatch(entry.name) and entry.is_file()
    ]
    return sorted(ids)


class Segment:
    """One append-only file of records. The file is created if missing."""

    def __init__(self, path: pathlib.Path, seg_id: int) -> None:
        self._path = pathlib.Path(path)
        self._seg_id = seg_id
        self._path.touch(exist_ok=True)
        self._size = self._path.stat().st_size
        self._fh: BinaryIO | None = None
        self._closed = False
        # Byte length of the well-formed prefix, known once scan() has finished.
        self._valid_size: int | None = None

    @property
    def path(self) -> pathlib.Path:
        return self._path

    @property
    def seg_id(self) -> int:
        return self._seg_id

    @property
    def size(self) -> int:
        return self._size

    def discard_tail(self) -> None:
        """Truncate a partial record found at the end of the file by scan()."""
        if self._valid_size is not None and self._valid_size < self._size:
            self._close_handle()
            os.truncate(self._path, self._valid_size)
            self._size = self._valid_size

    def append(self, blob: bytes) -> int:
        """Append ``blob`` at the end of the file and return its offset."""
        if self._closed:
            raise ValueError("segment is closed")
        if self._fh is None:
            self._fh = open(self._path, "ab")
        offset = self._size
        self._fh.write(blob)
        self._fh.flush()
        self._size += len(blob)
        return offset

    def scan(self) -> Iterator[tuple[str, str | None, int]]:
        """Yield ``(key, value, offset)`` for every record, tolerating a partial tail."""
        data = self._path.read_bytes()
        offset = 0
        while offset < len(data):
            try:
                key, value, total = decode_record(data, offset)
            except IncompleteRecordError:
                break
            except CorruptRecordError as exc:
                raise CorruptSegmentError(self._path, offset, str(exc)) from None
            yield key, value, offset
            offset += total
        self._valid_size = offset

    def read_at(self, offset: int) -> tuple[str, str | None, int]:
        """Decode the single record stored at ``offset``."""
        with open(self._path, "rb") as fh:
            fh.seek(offset)
            header = fh.read(HEADER_SIZE)
            try:
                total = record_size(header)
                data = header + fh.read(total - HEADER_SIZE)
                return decode_record(data)
            except (CorruptRecordError, IncompleteRecordError) as exc:
                raise CorruptSegmentError(self._path, offset, str(exc)) from None

    def _close_handle(self) -> None:
        if self._fh is not None:
            self._fh.close()
            self._fh = None

    def close(self) -> None:
        self._close_handle()
        self._closed = True

"""In-memory index mapping each key to the location of its newest record."""

from __future__ import annotations

import dataclasses


@dataclasses.dataclass(frozen=True)
class Location:
    seg_id: int
    offset: int


class Index:
    def __init__(self) -> None:
        self._entries: dict[str, tuple[Location, bool]] = {}
        self._tombstones = 0

    def put(self, key: str, loc: Location, *, tombstone: bool) -> None:
        old = self._entries.get(key)
        if old is not None and old[1]:
            self._tombstones -= 1
        if tombstone:
            self._tombstones += 1
        self._entries[key] = (loc, tombstone)

    def get(self, key: str) -> Location | None:
        entry = self._entries.get(key)
        if entry is None or entry[1]:
            return None
        return entry[0]

    def live_keys(self) -> list[str]:
        live = [(loc.seg_id, loc.offset, key) for key, (loc, dead) in self._entries.items() if not dead]
        live.sort()
        return [key for _, _, key in live]

    def tombstone_count(self) -> int:
        return self._tombstones

    def __len__(self) -> int:
        return len(self._entries) - self._tombstones

"""KVStore: a durable key-value store on append-only segments."""

from __future__ import annotations

import dataclasses
import os
import pathlib

from .index import Index, Location
from .record import encode_key, encode_record
from .segment import Segment, segment_ids, segment_path


@dataclasses.dataclass(frozen=True)
class Stats:
    live_keys: int
    tombstones: int
    total_records: int
    dead_records: int
    segment_count: int
    bytes_on_disk: int


class KVStore:
    def __init__(self, root: str | os.PathLike, *, max_segment_bytes: int = 4096) -> None:
        if (
            not isinstance(max_segment_bytes, int)
            or isinstance(max_segment_bytes, bool)
            or max_segment_bytes < 16
        ):
            raise ValueError("max_segment_bytes must be an int >= 16")
        self._root = pathlib.Path(root)
        self._max = max_segment_bytes
        self._closed = False
        self._segments: dict[int, Segment] = {}
        self._index = Index()
        self._total_records = 0
        self._root.mkdir(parents=True, exist_ok=True)
        try:
            self._recover()
        except BaseException:
            self._close_segments()
            raise

    @property
    def root(self) -> pathlib.Path:
        return self._root

    def _recover(self) -> None:
        for seg_id in segment_ids(self._root):
            seg = Segment(segment_path(self._root, seg_id), seg_id)
            self._segments[seg_id] = seg
            for key, value, offset in seg.scan():
                self._index.put(key, Location(seg_id, offset), tombstone=value is None)
                self._total_records += 1
        if not self._segments:
            self._segments[1] = Segment(segment_path(self._root, 1), 1)
        self._active = self._segments[max(self._segments)]

    def _check_open(self) -> None:
        if self._closed:
            raise ValueError("store is closed")

    def _append(self, key: str, value: str | None) -> None:
        blob = encode_record(key, value)
        # A partial record left by a crash must go before new bytes follow it.
        self._active.discard_tail()
        active = self._active
        if active.size > 0 and active.size + len(blob) > self._max:
            new_id = active.seg_id + 1
            active = Segment(segment_path(self._root, new_id), new_id)
            self._segments[new_id] = active
            self._active.close()
            self._active = active
        offset = active.append(blob)
        self._index.put(key, Location(active.seg_id, offset), tombstone=value is None)
        self._total_records += 1

    def set(self, key: str, value: str) -> None:
        self._check_open()
        if not isinstance(value, str):
            raise TypeError(f"value must be str, not {type(value).__name__}")
        self._append(key, value)

    def get(self, key: str) -> str | None:
        self._check_open()
        encode_key(key)
        loc = self._index.get(key)
        if loc is None:
            return None
        _, value, _ = self._segments[loc.seg_id].read_at(loc.offset)
        return value

    def delete(self, key: str) -> bool:
        self._check_open()
        encode_key(key)
        if self._index.get(key) is None:
            return False
        self._append(key, None)
        return True

    def keys(self) -> list[str]:
        self._check_open()
        return self._index.live_keys()

    def stats(self) -> Stats:
        self._check_open()
        ids = segment_ids(self._root)
        size = sum(segment_path(self._root, i).stat().st_size for i in ids)
        live = len(self._index)
        tombs = self._index.tombstone_count()
        return Stats(
            live_keys=live,
            tombstones=tombs,
            total_records=self._total_records,
            dead_records=self._total_records - live - tombs,
            segment_count=len(ids),
            bytes_on_disk=size,
        )

    def _install_compacted(self, seg_id: int, entries: list[tuple[str, int]]) -> int:
        """Swap in compacted segment ``seg_id``; delete older segment files.

        ``entries`` lists ``(key, offset)`` pairs of the new segment. Returns the
        number of old segment files removed.
        """
        self._close_segments()
        removed = 0
        for old_id in segment_ids(self._root):
            if old_id != seg_id:
                segment_path(self._root, old_id).unlink()
                removed += 1
        seg = Segment(segment_path(self._root, seg_id), seg_id)
        self._segments = {seg_id: seg}
        self._active = seg
        self._index = Index()
        for key, offset in entries:
            self._index.put(key, Location(seg_id, offset), tombstone=False)
        self._total_records = len(entries)
        return removed

    def _close_segments(self) -> None:
        for seg in self._segments.values():
            seg.close()

    def close(self) -> None:
        if not self._closed:
            self._close_segments()
            self._closed = True

    def __enter__(self) -> "KVStore":
        self._check_open()
        return self

    def __exit__(self, *exc: object) -> None:
        self.close()

"""Command-line interface: ``python -m kvstore ROOT COMMAND [ARGS...]``."""

from __future__ import annotations

import argparse
import sys
from typing import Callable

from .compact import compact
from .errors import CorruptSegmentError
from .store import KVStore


def _positive_int(text: str) -> int:
    try:
        number = int(text)
    except ValueError:
        raise argparse.ArgumentTypeError(f"not an integer: {text!r}") from None
    if number <= 0:
        raise argparse.ArgumentTypeError(f"must be a positive integer: {text!r}")
    return number


def _build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(prog="python -m kvstore")
    parser.add_argument("--max-segment-bytes", type=_positive_int, default=4096)
    parser.add_argument("root")
    sub = parser.add_subparsers(dest="command", required=True, metavar="COMMAND")
    specs = {"set": ["key", "value"], "get": ["key"], "delete": ["key"],
             "list": [], "compact": [], "stats": []}
    for name, params in specs.items():
        cmd = sub.add_parser(name)
        # Also accept the global flag after the command; SUPPRESS keeps the default.
        cmd.add_argument("--max-segment-bytes", type=_positive_int, default=argparse.SUPPRESS)
        for param in params:
            cmd.add_argument(param)
    return parser


def _cmd_set(store: KVStore, args: argparse.Namespace) -> tuple[int, str]:
    store.set(args.key, args.value)
    return 0, ""


def _cmd_get(store: KVStore, args: argparse.Namespace) -> tuple[int, str]:
    value = store.get(args.key)
    return (1, "") if value is None else (0, value + "\n")


def _cmd_delete(store: KVStore, args: argparse.Namespace) -> tuple[int, str]:
    return (0, "") if store.delete(args.key) else (1, "")


def _cmd_list(store: KVStore, args: argparse.Namespace) -> tuple[int, str]:
    return 0, "".join(key + "\n" for key in store.keys())


def _cmd_compact(store: KVStore, args: argparse.Namespace) -> tuple[int, str]:
    r = compact(store)
    return 0, (
        f"removed={r.segments_removed} written={r.records_written} "
        f"dropped={r.records_dropped} reclaimed={r.bytes_reclaimed}\n"
    )


def _cmd_stats(store: KVStore, args: argparse.Namespace) -> tuple[int, str]:
    s = store.stats()
    return 0, (
        f"live_keys={s.live_keys} tombstones={s.tombstones} "
        f"total_records={s.total_records} dead_records={s.dead_records} "
        f"segment_count={s.segment_count} bytes_on_disk={s.bytes_on_disk}\n"
    )


_HANDLERS: dict[str, Callable[[KVStore, argparse.Namespace], tuple[int, str]]] = {
    "set": _cmd_set,
    "get": _cmd_get,
    "delete": _cmd_delete,
    "list": _cmd_list,
    "compact": _cmd_compact,
    "stats": _cmd_stats,
}


def main(argv: list[str] | None = None) -> int:
    parser = _build_parser()
    try:
        args = parser.parse_args(argv)
    except SystemExit as exc:
        return exc.code if isinstance(exc.code, int) else 2
    try:
        with KVStore(args.root, max_segment_bytes=args.max_segment_bytes) as store:
            code, output = _HANDLERS[args.command](store, args)
    except CorruptSegmentError as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 3
    except (ValueError, TypeError) as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 2
    # Output is buffered until success so failures never write to stdout.
    sys.stdout.write(output)
    sys.stdout.flush()
    return code


if __name__ == "__main__":
    sys.exit(main())

